import { watchDom } from '../core/observer';
import { wasApplied, markApplied } from '../utils/dom';

const LOGO_URL = '/ptv-logo/banner-light.png';

function enhanceLoginPage() {
    const loginPage = document.querySelector('.loginPage, .manualLoginPage, #loginPage');
    if (!loginPage || wasApplied(loginPage, 'ptvLogin')) return;

    markApplied(loginPage, 'ptvLogin');
    loginPage.classList.add('ptv-login-page');

    const form = loginPage.querySelector('form, .manualLoginForm, .readOnlyContent');
    if (!form || form.querySelector('.ptv-login-brand')) return;

    const brand = document.createElement('div');
    brand.className = 'ptv-login-brand';
    brand.innerHTML = `
        <img class="ptv-login-logo" src="${LOGO_URL}" alt="PiggieTV">
        <div class="ptv-login-tagline">MOVIES • TV SHOWS • ANIME • BOOKS • MANGA • GAMES</div>
    `;

    form.prepend(brand);
}

watchDom(enhanceLoginPage);
enhanceLoginPage();
